<script setup lang="ts">
import type { Crop } from '~/types/api'; const props=defineProps<{ modelValue:string; crops:Crop[] }>(); defineEmits<{ 'update:modelValue':[value:string] }>(); const sortedCrops=computed(()=>[...props.crops].sort((left,right)=>{const leftPriority=left.code==='TRIGO'?0:1;const rightPriority=right.code==='TRIGO'?0:1;return leftPriority-rightPriority||left.name.localeCompare(right.name,'es')}))
</script>
<template><label><span class="label">Cultivo</span><select class="select" :value="modelValue" @change="$emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option v-for="crop in sortedCrops" :key="crop.id" :value="crop.code">{{ crop.name }}<template v-if="crop.rules_status !== 'active'"> · Configuración pendiente</template></option></select></label></template>
